// 2026-07-13 rework: the old single GET /executions?limit=250 window shrank to ~1 day
// once the 15-min/30-min/hourly workflows shipped, false-alerting weekly/daily jobs.
// Now each monitored workflow gets its own ?workflowId=&limit=1 lookup (Fetch Last
// Execution, one item per heartbeat_expected row, order-preserving), so max_silence_hours
// is always honored. Note: n8n cloud execution retention still bounds how far back
// 'last run' can be seen — keep max_silence_hours within the retention period.
const expected = $('Get Expected Workflows').all().map(i => i.json);
const activeIds = new Set((($('Fetch Active Workflows').first().json || {}).data || []).map(w => w.id));
const lastResp = $input.all();
const now = Date.now();
const problems = [];
for (let i = 0; i < expected.length; i++) {
  const w = expected[i];
  if (!activeIds.has(w.workflow_id)) {
    problems.push({ workflow_id: w.workflow_id, name: w.name, problem: 'NOT ACTIVE — deactivated or archived (the Sign Link failure mode)' });
    continue;
  }
  if (w.kind === 'schedule') {
    const limitH = w.max_silence_hours || 26;
    const d = ((lastResp[i] || {}).json || {}).data || [];
    const last = d.length ? new Date(d[0].startedAt).getTime() : null;
    if (!last) {
      problems.push({ workflow_id: w.workflow_id, name: w.name, problem: 'active but no execution found at all (or outside n8n execution retention) — schedule may not be firing' });
    } else if (now - last > limitH * 3600 * 1000) {
      problems.push({ workflow_id: w.workflow_id, name: w.name, problem: 'active but last run was ' + Math.round((now - last) / 3600000) + 'h ago (limit ' + limitH + 'h)' });
    }
  }
}
return problems.map(p => ({ json: p }));

